    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))
    # Repeated diagonal colors continue outward from the seed pair, stopping at
    # any other colored cell (which acts as an obstruction/marker).
    directions = ((1, -1), (1, 1))
    for dr, dc in directions:
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                nr, nc = r + dr, c + dc
                if color == bg or not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] != color:
                    continue
                # Walk outward from both ends of the adjacent seed pair.
                for rr, cc, sr, sc in ((r, c, -dr, -dc), (nr, nc, dr, dc)):
                    rr += sr
                    cc += sc
                    while 0 <= rr < h and 0 <= cc < w:
                        if out[rr][cc] != bg:
                            break
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out
